\item[S1]J. Qian, F. Schalekamp, D. P. Williamson, A. van Zuylen, On the integrality gap of the subtour LP for the 1,2-TSP, Math. Program. 148 (2014) 411-417.
\url{https://doi.org/10.1007/s10107-014-0835-4}.
